use serde :: { Deserialize , Serialize } ; use pretty_assertions :: assert_eq ; use super :: * ; impl URLParamSpec { # [doc = " Creates a `URLParamSpec` with only a name, rendering as a free-text"] # [doc = " input."] pub fn new (name : impl Into < URLParam >) -> Self { Self { name : name . into () , options : None , optional : false } } # [doc = " Creates a `URLParamSpec` with preset options, rendering as a dropdown."] pub fn with_options (name : impl Into < URLParam > , options : Vec < String >) -> Self { Self { name : name . into () , options : Some (options) , optional : false } } # [doc = " Creates an optional `URLParamSpec` that may be left blank."] pub fn optional (name : impl Into < URLParam >) -> Self { Self { name : name . into () , options : None , optional : true } } }